    10→// RODataColumn represents a read-only data column sidecar with its block root.
    11→type RODataColumn struct {
    12→	*ethpb.DataColumnSidecar
    13→	root [fieldparams.RootLength]byte
    14→}
    15→
    16→func roDataColumnNilCheck(dc *ethpb.DataColumnSidecar) error {
    17→	// Check if the data column is nil.
    18→	if dc == nil {
    19→		return errNilDataColumn
    20→	}
    21→
    22→	// Check if the data column header is nil.
    23→	if dc.SignedBlockHeader == nil || dc.SignedBlockHeader.Header == nil {
    24→		return errNilBlockHeader
    25→	}
    26→
    27→	// Check if the data column signature is nil.
    28→	if len(dc.SignedBlockHeader.Signature) == 0 {
    29→		return errMissingBlockSignature
    30→	}
    31→
    32→	return nil
    33→}
    34→
    35→// NewRODataColumn creates a new RODataColumn by computing the HashTreeRoot of the header.
    36→func NewRODataColumn(dc *ethpb.DataColumnSidecar) (RODataColumn, error) {
    37→	if err := roDataColumnNilCheck(dc); err != nil {
    38→		return RODataColumn{}, err
    39→	}
    40→
    41→	root, err := dc.SignedBlockHeader.Header.HashTreeRoot()
    42→	if err != nil {
    43→		return RODataColumn{}, err
    44→	}
    45→
    46→	return RODataColumn{DataColumnSidecar: dc, root: root}, nil
    47→}
    48→
    49→// NewRODataColumnWithRoot creates a new RODataColumn with a given root.
    50→func NewRODataColumnWithRoot(dc *ethpb.DataColumnSidecar, root [fieldparams.RootLength]byte) (RODataColumn, error) {
    51→	// Check if the data column is nil.
    52→	if err := roDataColumnNilCheck(dc); err != nil {
    53→		return RODataColumn{}, err
    54→	}
    55→
    56→	return RODataColumn{DataColumnSidecar: dc, root: root}, nil
    57→}
    58→
    59→// BlockRoot returns the root of the block.
    60→func (dc *RODataColumn) BlockRoot() [fieldparams.RootLength]byte {
    61→	return dc.root
    62→}
    63→
    64→// Slot returns the slot of the data column sidecar.
    65→func (dc *RODataColumn) Slot() primitives.Slot {
    66→	return dc.SignedBlockHeader.Header.Slot
    67→}
    68→
    69→// ProposerIndex returns the proposer index of the data column sidecar.
    70→func (dc *RODataColumn) ProposerIndex() primitives.ValidatorIndex {
    71→	return dc.SignedBlockHeader.Header.ProposerIndex
    72→}
    73→
    74→// ParentRoot returns the parent root of the data column sidecar.
    75→func (dc *RODataColumn) ParentRoot() [fieldparams.RootLength]byte {
    76→	return bytesutil.ToBytes32(dc.SignedBlockHeader.Header.ParentRoot)
    77→}
